  if (ADMIN_KIDS === null && !ui.adminLoading) { ui.adminLoading = true; tapi("admin/students?q=").then(r => { ADMIN_KIDS = r; }).catch(() => {}).finally(() => { ui.adminLoading = false; draw(); }); }
